1	import { Injectable, NotFoundException, BadRequestException, ForbiddenException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	import { GeocodingService } from '../motoboy/geocoding.service';
4	import { SalaoService } from '../salao/salao.service';
5	import { EstoqueService } from '../estoque/estoque.service';
6	import { CombosService, ItemExpandido } from '../combos/combos.service';
7	
8	const STATUS_VALIDOS = ['pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery', 'delivered', 'canceled'] as const;
9	type Status = typeof STATUS_VALIDOS[number];
10	
11	@Injectable()
12	export class PedidosService {
13	  constructor(
14	    private supabase: SupabaseService,
15	    private geocoding: GeocodingService,
16	    private salaoService: SalaoService,
17	    private estoque: EstoqueService,
18	    private combos: CombosService,
19	  ) {}
20	
21	  // Roteia os itens do pedido delivery pro mesmo mecanismo de KDS por setor que o
22	  // módulo Salão já usa: copia impressora_id do produto pro item, marca status
23	  // "enviado" (aparece em Produção/Bar/Cozinha filtrado por setor) e gera job de
24	  // impressão por setor pras impressoras com agente local pareado. Idempotente —
25	  // só processa item que ainda não foi enviado (enviado_em null), então pode chamar
26	  // de novo sem duplicar (ex: pedido volta de "confirmed" -> "pending" -> "confirmed").
27	  private async rotearItensParaSetor(pedidoId: number, restauranteId: number) {
28	    const { data: pendentes, error } = await this.supabase.client
29	      .from('order_items')
30	      .select('id, quantity, products(name, description, impressora_id, impressoras(id, nome, setor, nome_sistema))')
31	      .eq('order_id', pedidoId)
32	      .is('enviado_em', null);
33	    if (error) throw error;
34	    if (!pendentes?.length) return;
35	
36	    const agora = new Date().toISOString();
37	    await this.supabase.client
38	      .from('order_items')
39	      .update({ status: 'enviado', enviado_em: agora })
40	      .in('id', pendentes.map((p: any) => p.id));
41	
42	    for (const item of pendentes as any[]) {
43	      const impressoraId = item.products?.impressora_id ?? null;
44	      if (impressoraId) {
45	        await this.supabase.client.from('order_items').update({ impressora_id: impressoraId }).eq('id', item.id);
46	      }
47	    }
48	
49	    const grupos = new Map<string, { setor: string; impressora_id: number; nome_sistema: string | null; itens: any[] }>();
50	    for (const item of pendentes as any[]) {
51	      const impressora = item.products?.impressoras;
52	      if (!impressora?.id) continue; // produto sem impressora configurada — não gera job
53	      const chave = String(impressora.id);
54	      if (!grupos.has(chave)) {
55	        grupos.set(chave, { setor: impressora.setor, impressora_id: impressora.id, nome_sistema: impressora.nome_sistema ?? null, itens: [] });
56	      }
57	      grupos.get(chave)!.itens.push({
58	        product_name: item.products?.name,
59	        description: item.products?.description,
60	        quantity: item.quantity,
61	      });
62	    }
63	
64	    const comandaLike = { cliente_mesa_nome: `Pedido delivery #${pedidoId}` };
65	    for (const grupo of grupos.values()) {
66	      if (!grupo.nome_sistema) continue; // sem agente local pareado — sem job, staff reimprime pela tela do setor
67	      const conteudo = this.salaoService.formatarTicketTexto(grupo.setor, comandaLike, grupo.itens);
68	      const { error: errJob } = await this.supabase.client.from('impressao_jobs').insert({
69	        restaurant_id: restauranteId,
70	        impressora_id: grupo.impressora_id,
71	        conteudo,
72	      });
73	      if (errJob) throw errJob;
74	    }
75	  }
76	
77	  private async geocodificarEnderecoCliente(customerId: number) {
78	    const { data: customer } = await this.supabase.client
79	      .from('customers')
80	      .select('address_json, address_geocode_hash')
81	      .eq('id', customerId)
82	      .maybeSingle();
83	    if (!customer) return;
84	
85	    const resultado = await this.geocoding.geocodificarSeNecessario(customer.address_json, customer.address_geocode_hash);
86	    if (!resultado) return;
87	
88	    await this.supabase.client
89	      .from('customers')
90	      .update({
91	        lat: resultado.lat,
92	        lng: resultado.lng,
93	        address_geocode_hash: resultado.hash,
94	        address_geocoded_at: new Date().toISOString(),
95	      })
96	      .eq('id', customerId);
97	  }
98	
99	  async listar(filtros: {
100	    empresa_id?: number;
101	    status?: string;
102	    user_id?: string;
103	    data_inicio?: string;
104	    data_fim?: string;
105	    limite?: number;
106	  }) {
107	    let query = this.supabase.client
108	      .from('orders')
109	      .select('id, total, frete_cobrado, status, payment_method, restaurant_id, customer_id, user_id, created_at')
110	      .order('created_at', { ascending: false })
111	      .limit(filtros.limite ?? 50);
112	
113	    if (filtros.empresa_id) query = query.eq('restaurant_id', filtros.empresa_id);
114	    if (filtros.status) query = query.eq('status', filtros.status);
115	    if (filtros.user_id) query = query.eq('user_id', filtros.user_id);
116	    if (filtros.data_inicio) query = query.gte('created_at', filtros.data_inicio);
117	    if (filtros.data_fim) query = query.lte('created_at', filtros.data_fim + 'T23:59:59');
118	
119	    const { data, error } = await query;
120	    if (error) throw error;
121	    return { pedidos: data, total: data?.length ?? 0 };
122	  }
123	
124	  async buscar(id: number) {
125	    const { data: pedido, error } = await this.supabase.client
126	      .from('orders')
127	      .select('id, total, troco_para, frete_cobrado, entrega_pagamento, status, payment_method, restaurant_id, customer_id, user_id, motoboy_id, motoboy_lat, motoboy_lng, motoboy_location_at, delivery_notes, delivery_occurrence, cancel_reason, created_at, updated_at')
128	      .eq('id', id)
129	      .maybeSingle();
130	
131	    if (error) throw error;
132	    if (!pedido) throw new NotFoundException(`Pedido ${id} não encontrado`);
133	
134	    const [{ data: itensRaw }, { data: cliente }, { data: empresa }, { data: motoboy }, { data: pagamento }] = await Promise.all([
135	      this.supabase.client
136	        .from('order_items')
137	        .select('id, quantity, unit_price, product_id, combo_nome, combo_quantidade, status, enviado_em, preparando_em')
138	        .eq('order_id', id),
139	      pedido.customer_id
140	        ? this.supabase.client.from('customers').select('id, name, email, phone_e164, address_json').eq('id', pedido.customer_id).maybeSingle()
141	        : Promise.resolve({ data: null }),
142	      this.supabase.client
143	        .from('restaurants')
144	        .select('id, name, comissao_pct, address')
145	        .eq('id', pedido.restaurant_id)
146	        .maybeSingle(),
147	      pedido.motoboy_id
148	        ? this.supabase.client.from('motoboys').select('id, name, phone, access_token').eq('id', pedido.motoboy_id).maybeSingle()
149	        : Promise.resolve({ data: null }),
150	      this.supabase.client.from('pagamentos').select('id, valor, tipo, status').eq('order_id', id).eq('status', 'paid').maybeSingle(),
151	    ]);
152	
153	    // Enrich items with product names
154	    let itens = itensRaw ?? [];
155	    if (itens.length > 0) {
156	      const prodIds = itens.map((i: any) => i.product_id);
157	      const { data: prods } = await this.supabase.client.from('products').select('id, name').in('id', prodIds);
158	      const prodMap = Object.fromEntries((prods ?? []).map((p: any) => [p.id, p.name]));
159	      itens = itens.map((i: any) => ({ ...i, product_name: prodMap[i.product_id] ?? `Produto #${i.product_id}` }));
160	    }
161	
162	    return { pedido, itens, cliente, empresa, motoboy, pagamento_pago: pagamento ?? null };
163	  }
164	
165	  async criar(body: {
166	    restaurant_id: number;
167	    customer_id?: number;
168	    payment_method: string;
169	    troco_para?: number;
170	    user_id: string;
171	    itens: { product_id?: number; combo_id?: number; quantity: number }[];
172	  }) {
173	    if (!body.itens?.length) throw new BadRequestException('Pedido precisa de pelo menos 1 item');
174	
175	    const itensDiretos = body.itens.filter((i) => i.product_id != null);
176	    const itensCombo = body.itens.filter((i) => i.combo_id != null);
177	
178	    // Busca preços dos produtos vendidos diretamente (fora de combo)
179	    const prodIds = itensDiretos.map((i) => i.product_id as number);
180	    const { data: produtos, error: errProd } = await this.supabase.client
181	      .from('products')
182	      .select('id, price, is_active')
183	      .in('id', prodIds.length ? prodIds : [0]);
184	
185	    if (errProd) throw errProd;
186	
187	    const prodMap = Object.fromEntries((produtos ?? []).map((p) => [p.id, p]));
188	
189	    for (const item of itensDiretos) {
190	      const prod = prodMap[item.product_id as number];
191	      if (!prod) throw new BadRequestException(`Produto ${item.product_id} não encontrado`);
192	      if (!prod.is_active) throw new BadRequestException(`Produto ${item.product_id} inativo`);
193	    }
194	
195	    // Combo não é vendável direto — vira as linhas dos produtos reais que o compõem,
196	    // com preço escalado pra bater o valor promocional do combo (ver CombosService).
197	    const linhasCombo: ItemExpandido[] = (
198	      await Promise.all(itensCombo.map((i) => this.combos.expandir(i.combo_id as number, i.quantity, body.restaurant_id)))
199	    ).flat();
200	
201	    const linhasDiretas: ItemExpandido[] = itensDiretos.map((item) => ({
202	      product_id: item.product_id as number,
203	      quantity: item.quantity,
204	      unit_price: prodMap[item.product_id as number].price,
