// Move só esse item de "aguardando" (enviado) pra "preparando" — ação por item, não
// por comanda inteira (cada prato tem seu próprio ritmo de preparo).
async iniciarPreparoItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();
  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  const { error } = await this.supabase.client
    .from('order_items')
    .update({ status: 'preparando', preparando_em: new Date().toISOString() })
    .eq('id', itemId);
  if (error) throw error;

  return { ok: true };
}

async marcarItemPronto(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  const { error } = await this.supabase.client.from('order_items').update({ status: 'pronto', pronto_em: new Date().toISOString() }).eq('id', itemId);
  if (error) throw error;
  return { ok: true };
}

// Desfaz clique errado na Cozinha/Bar — volta um passo (pronto -> preparando ->
// enviado/aguardando). "Enviado" já é o início da fila do KDS, não dá pra voltar mais.
async voltarStatusItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  if (item.status === 'pronto') {
    const { error } = await this.supabase.client
      .from('order_items')
      .update({ status: 'preparando', pronto_em: null })
      .eq('id', itemId);
    if (error) throw error;
    return { ok: true, status: 'preparando' };
  }

  if (item.status === 'preparando') {
    const { error } = await this.supabase.client
      .from('order_items')
      .update({ status: 'enviado', preparando_em: null })
      .eq('id', itemId);
    if (error) throw error;
    return { ok: true, status: 'enviado' };
  }

  throw new BadRequestException('Item já está aguardando — não dá pra voltar mais');
}

// Cancela item ainda "Aguardando Preparo" — some da fila de Produção e Cozinha
// (ambas leem por status via GET /kds). Só permite nesse estágio: depois que a
// cozinha já começou o preparo, cancelar teria que envolver estorno/decisão do
// dono, fora do escopo desse botão rápido.
async cancelarItem(itemId: number, restaurantId: number) {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, order_id, product_id, quantity, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }

  if (item.status !== 'enviado') {
    throw new BadRequestException('Só é possível cancelar um item enquanto está Aguardando Preparo');
  }

  const { error } = await this.supabase.client
    .from('order_items')
    .update({ status: 'cancelado', cancelado_em: new Date().toISOString() })
    .eq('id', itemId);
  if (error) throw error;

  await this.estoque.restaurarItens([{ product_id: item.product_id, quantity: item.quantity }]);

  return { ok: true };
}

// Adiantar/atrasar item na fila "Aguardando Preparo" — troca de posição com o vizinho
// (cima/baixo). Resequencia ordem_fila de TODOS os itens "enviado" do setor pra manter
// consistência: sem isso, itens ainda sem ordem_fila (null) ficariam intercalados de
// forma imprevisível com os já reordenados.
async moverPosicaoItem(itemId: number, restaurantId: number, direcao: 'cima' | 'baixo') {
  const { data: item } = await this.supabase.client
    .from('order_items')
    .select('id, status, impressora_id, order_id, orders(restaurant_id)')
    .eq('id', itemId)
    .maybeSingle();

  if (!item || (item as any).orders?.restaurant_id !== restaurantId) {
    throw new NotFoundException('Item não encontrado');
  }
  if (item.status !== 'enviado') {
    throw new BadRequestException('Só é possível reordenar um item enquanto está Aguardando Preparo');
  }

  const { data: fila, error } = await this.supabase.client
    .from('order_items')
    .select('id, ordem_fila, enviado_em')
    .eq('impressora_id', item.impressora_id)
    .eq('status', 'enviado')
    .order('ordem_fila', { ascending: true, nullsFirst: false })
    .order('enviado_em', { ascending: true });
  if (error) throw error;

  const lista = fila as any[];
  const idx = lista.findIndex((i) => i.id === itemId);
  const swapIdx = direcao === 'cima' ? idx - 1 : idx + 1;
  if (idx === -1 || swapIdx < 0 || swapIdx >= lista.length) {
    throw new BadRequestException('Item já está na ponta da fila');
  }

  [lista[idx], lista[swapIdx]] = [lista[swapIdx], lista[idx]];

  await Promise.all(
    lista.map((i, novaPos) =>
      this.supabase.client.from('order_items').update({ ordem_fila: novaPos }).eq('id', i.id),
    ),
  );

  return { ok: true };
}

private readonly STATUS_ABERTOS = ['pending', 'confirmed', 'preparing', 'ready', 'motoboy_collecting', 'out_for_delivery'];
private readonly COMANDA_STATUS_ABERTOS = ['aberta', 'fechada_garcom'];

// Venda finalizada = entregue (delivery) ou paga (comanda do salão) — sem isso o
// resumo/KPI do dashboard ignorava toda venda do salão (comanda nunca vira 'delivered').
private readonly STATUS_VENDA_FINALIZADA = ['delivered', 'paga'];

// Comanda do salão pode ter N pagamentos com formas diferentes (parcial pelo garçom +
// resto pelo caixa) — orders.payment_method só guarda a última forma usada no
// fechamento, então pra decompor certo o "por forma de pagamento" precisa ir direto
// no ledger de comanda_pagamentos. Delivery continua com pagamento único (sem mudança).
private async buscarPagamentosPorComanda(pedidos: any[]): Promise<Map<number, { order_id: number; valor: number; valor_recebido: number | null; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>> {
  const idsComanda = pedidos.filter((p: any) => p.canal === 'presencial').map((p: any) => p.id);
  const mapa = new Map<number, { order_id: number; valor: number; valor_recebido: number | null; forma_pagamento: string; origem: string; troco: number; criado_em: string; taxa_cartao_valor: number }[]>();
  if (!idsComanda.length) return mapa;

  const { data } = await this.supabase.client
    .from('comanda_pagamentos')
    .select('order_id, valor, valor_recebido, forma_pagamento, origem, troco, criado_em, taxa_cartao_valor')
    .in('order_id', idsComanda);

  for (const p of (data ?? []) as any[]) {
    if (!mapa.has(p.order_id)) mapa.set(p.order_id, []);
    mapa.get(p.order_id)!.push({ order_id: p.order_id, valor: p.valor, valor_recebido: p.valor_recebido ?? null, forma_pagamento: p.forma_pagamento, origem: p.origem, troco: p.troco ?? 0, criado_em: p.criado_em, taxa_cartao_valor: p.taxa_cartao_valor ?? 0 });
  }

