  const cfg = (data?.payment_config ?? {}) as Record<string, any>;

  return {
    pagbank_sandbox: cfg.pagbank_sandbox ?? true,
    pagbank_webhook_url: cfg.pagbank_webhook_url ?? '',
    pagbank_token_masked: cfg.pagbank_token
