import { Body, Controller, Delete, Get, Param, ParseIntPipe, Patch, Post, Req, UseGuards } from '@nestjs/common';
import { GarcomGuard } from '../auth/garcom.guard';
import { GarcomAuthService } from './garcom-auth.service';
import { SalaoService } from './salao.service';
import type { AbrirComandaBody, ItemComandaBody } from './salao.service';

@Controller('garcom')
@UseGuards(GarcomGuard)
export class SalaoController {
  constructor(
    private service: SalaoService,
    private authService: GarcomAuthService,
  ) {}

  @Get('me')
  me(@Req() req: any) {
    return {
      id: req.garcomId,
      nome: req.garcomNome,
      restauranteAberto: req.restauranteAberto,
      permissoes: req.garcomPermissoes,
      salaoModo: req.salaoModo,
    };
  }

  @Post('logout')
  logout(@Req() req: any) {
    return this.authService.logout(req.garcomId);
  }

  @Get('mesas')
  mesas(@Req() req: any) {
    return this.service.mesas(req.garcomRestaurantId);
  }

  @Get('produtos')
  produtos(@Req() req: any) {
    return this.service.produtos(req.garcomRestaurantId);
  }

  @Get('combos')
  combos(@Req() req: any) {
    return this.service.combos(req.garcomRestaurantId);
  }

  @Get('comandas')
  minhasComandas(@Req() req: any) {
    return this.service.minhasComandas(req.garcomId);
  }

  @Get('itens-prontos')
  itensProntos(@Req() req: any) {
    return this.service.itensProntos(req.garcomId);
  }

  @Get('fila-cozinha')
  filaCozinha(@Req() req: any) {
    return this.service.filaCozinha(req.garcomRestaurantId);
  }

  @Get('comandas/:id')
  obterComanda(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    return this.service.obterComanda(id, req.garcomId);
  }

  @Post('comandas/abrir')
  abrir(@Body() body: AbrirComandaBody, @Req() req: any) {
    return this.service.abrirComanda(req.garcomId, req.garcomRestaurantId, body, req.restauranteAberto, req.salaoModo);
  }

  @Post('comandas/:id/itens')
  adicionarItens(@Param('id', ParseIntPipe) id: number, @Body() body: { itens: ItemComandaBody[] }, @Req() req: any) {
    return this.service.adicionarItens(id, req.garcomId, body.itens);
  }

  @Patch('comandas/:id/itens/:itemId')
  editarItem(
    @Param('id', ParseIntPipe) id: number,
    @Param('itemId', ParseIntPipe) itemId: number,
    @Body() body: { quantity?: number; observacao?: string },
    @Req() req: any,
  ) {
    return this.service.editarItem(id, req.garcomId, itemId, body);
  }

  @Delete('comandas/:id/itens/:itemId')
  removerItem(@Param('id', ParseIntPipe) id: number, @Param('itemId', ParseIntPipe) itemId: number, @Req() req: any) {
    return this.service.removerItem(id, req.garcomId, itemId);
  }

  @Patch('comandas/:id/itens/:itemId/observacao')
  editarObservacaoItem(
    @Param('id', ParseIntPipe) id: number,
    @Param('itemId', ParseIntPipe) itemId: number,
    @Body() body: { observacao: string },
    @Req() req: any,
  ) {
    return this.service.editarObservacaoItem(id, req.garcomId, itemId, body.observacao);
  }

  @Post('comandas/:id/dividir')
  dividirComanda(
    @Param('id', ParseIntPipe) id: number,
    @Body() body: { item_ids: number[]; cliente_nome: string; cliente_telefone?: string },
    @Req() req: any,
  ) {
    return this.service.dividirComanda(id, req.garcomId, body.item_ids, body.cliente_nome, body.cliente_telefone);
  }

  @Patch('comandas/:id/itens/:itemId/entregar')
  confirmarEntregaItem(@Param('id', ParseIntPipe) id: number, @Param('itemId', ParseIntPipe) itemId: number, @Req() req: any) {
    return this.service.confirmarEntregaItem(id, req.garcomId, itemId);
  }

  @Patch('comandas/:id/itens/:itemId/indo-buscar')
  indoBuscarItem(@Param('id', ParseIntPipe) id: number, @Param('itemId', ParseIntPipe) itemId: number, @Req() req: any) {
    return this.service.indoBuscarItem(id, req.garcomId, itemId);
  }

  @Patch('comandas/:id/conferencia-vista')
  marcarConferenciaVista(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    return this.service.marcarConferenciaVista(id, req.garcomId);
  }

  @Patch('comandas/:id/itens/:itemId/nao-entregar')
  naoEntregarItem(@Param('id', ParseIntPipe) id: number, @Param('itemId', ParseIntPipe) itemId: number, @Req() req: any) {
    return this.service.naoEntregarItem(id, req.garcomId, itemId);
  }

  @Patch('comandas/:id/cliente')
  editarCliente(
    @Param('id', ParseIntPipe) id: number,
    @Body() body: { cliente_nome: string; cliente_telefone: string },
    @Req() req: any,
  ) {
    return this.service.editarClienteMesa(id, req.garcomId, body);
  }

  @Post('comandas/:id/pagamento')
  registrarPagamento(
    @Param('id', ParseIntPipe) id: number,
    @Body() body: { valor: number; forma_pagamento: string; valor_recebido?: number; troco_via_pix?: boolean },
    @Req() req: any,
  ) {
    return this.service.registrarPagamentoComoGarcom(
      id, req.garcomId, body.valor, body.forma_pagamento, req.garcomPermissoes?.pagamento_parcial !== false, body.valor_recebido, body.troco_via_pix,
    );
  }

  @Patch('comandas/:id/pagamentos/:pagamentoId')
  editarPagamento(
    @Param('id', ParseIntPipe) id: number,
    @Param('pagamentoId', ParseIntPipe) pagamentoId: number,
    @Body() body: { valor: number; forma_pagamento: string },
    @Req() req: any,
  ) {
    return this.service.editarPagamentoComoGarcom(
      id, req.garcomId, pagamentoId, body.valor, body.forma_pagamento, req.garcomPermissoes?.pagamento_parcial !== false,
    );
  }

  @Delete('comandas/:id/pagamentos/:pagamentoId')
  removerPagamento(
    @Param('id', ParseIntPipe) id: number,
    @Param('pagamentoId', ParseIntPipe) pagamentoId: number,
    @Req() req: any,
  ) {
    return this.service.removerPagamentoComoGarcom(
      id, req.garcomId, pagamentoId, req.garcomPermissoes?.pagamento_parcial !== false,
    );
  }

  @Post('comandas/:id/enviar')
  enviar(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    return this.service.enviarItens(id, req.garcomId);
  }

  @Post('comandas/:id/fechar')
  fechar(@Param('id', ParseIntPipe) id: number, @Req() req: any) {
    return this.service.fecharComanda(id, req.garcomId);
  }
}

