1	import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	
4	export type LicencaStatus = {
5	  ativo: boolean; // false = esta instalação não tem LICENCA_SERIAL configurado (deployment central multi-tenant)
6	  bloqueado: boolean;
7	  revogado: boolean;
8	  dias_atraso: number;
9	  plano_nome: string | null;
10	  proxima_cobranca: string | null;
11	  ultima_consulta_ok: boolean;
12	  ultima_consulta_em: string | null;
13	};
14	
15	const INTERVALO_PADRAO_MIN = 5;
16	
17	// Só roda quando LICENCA_SERIAL está setado no .env — instalação central
18	// multi-tenant nunca configura isso, então fica sempre { ativo: false } lá.
19	@Injectable()
20	export class LicencaService implements OnModuleInit {
21	  private readonly logger = new Logger(LicencaService.name);
22	  private status: LicencaStatus = {
23	    ativo: false,
24	    bloqueado: false,
25	    revogado: false,
26	    dias_atraso: 0,
27	    plano_nome: null,
28	    proxima_cobranca: null,
29	    ultima_consulta_ok: false,
30	    ultima_consulta_em: null,
31	  };
32	
33	  constructor(private config: ConfigService) {}
34	
35	  onModuleInit() {
36	    const serial = this.config.get<string>('LICENCA_SERIAL');
37	    if (!serial) return;
38	
39	    this.status.ativo = true;
40	    const minutos = Number(this.config.get<string>('LICENCA_CHECKIN_INTERVALO_MIN')) || INTERVALO_PADRAO_MIN;
41	    this.checkin();
42	    setInterval(() => this.checkin(), minutos * 60 * 1000);
43	  }
44	
45	  getStatus(): LicencaStatus {
46	    return this.status;
47	  }
