1	import { BadRequestException, Body, Controller, Get, Post, Req, UseGuards } from '@nestjs/common';
2	import { JwtGuard } from '../auth/jwt.guard';
3	import { RestaurantOwnerGuard } from '../auth/restaurant-owner.guard';
4	import { SupabaseService } from '../supabase/supabase.service';
5	import { GeocodingService } from '../motoboy/geocoding.service';
6	import { PlanosService } from '../planos/planos.service';
7	import { UsuariosService } from '../usuarios/usuarios.service';
8	
9	@Controller('restaurante')
10	export class OnboardingController {
11	  constructor(
12	    private supabase: SupabaseService,
13	    private geocoding: GeocodingService,
14	    private planos: PlanosService,
15	    private usuarios: UsuariosService,
16	  ) {}
17	
18	  // Público (sem guard) — a wizard de cadastro mostra os planos antes do
19	  // usuário logar/criar conta, pra ele escolher já na primeira etapa.
20	  @Get('planos-disponiveis')
21	  planosDisponiveis() {
22	    return this.planos.listarPlanosAtivos('saas');
23	  }
24	
25	  private normalizarDigitos(v?: string | null): string | null {
26	    const d = (v ?? '').replace(/\D/g, '');
27	    return d || null;
28	  }
29	
30	  private normalizarEmail(v?: string | null): string | null {
31	    const e = (v ?? '').trim().toLowerCase();
32	    return e || null;
33	  }
34	
35	  // Checa CNPJ/WhatsApp/email contra os demais restaurantes (excluindo o
36	  // próprio, pra reenvio do mesmo formulário não acusar conflito consigo
37	  // mesmo). CNPJ é opcional — null nunca conflita (UNIQUE do Postgres também
38	  // trata assim).
39	  private async checarDuplicados(
40	    restaurantId: number,
41	    valores: { cnpj: string | null; whatsapp: string | null; email: string | null },
42	  ) {
43	    const ors: string[] = [];
44	    if (valores.cnpj) ors.push(`cnpj.eq.${valores.cnpj}`);
45	    if (valores.whatsapp) ors.push(`whatsapp.eq.${valores.whatsapp}`);
46	    if (valores.email) ors.push(`email.eq.${valores.email}`);
47	    if (!ors.length) return { cnpj: false, whatsapp: false, email: false };
48	
49	    const { data, error } = await this.supabase.client
50	      .from('restaurants')
51	      .select('id, cnpj, whatsapp, email')
52	      .or(ors.join(','))
53	      .neq('id', restaurantId);
54	    if (error) throw error;
55	
56	    const conflita = (campo: 'cnpj' | 'whatsapp' | 'email', valor: string | null) =>
57	      !!valor && (data ?? []).some((r: any) => r[campo] === valor);
58	
59	    return {
60	      cnpj: conflita('cnpj', valores.cnpj),
61	      whatsapp: conflita('whatsapp', valores.whatsapp),
62	      email: conflita('email', valores.email),
63	    };
64	  }
65	
66	  // Checagem em tempo real usada pela wizard (passos "business"/"contact")
67	  // pra avisar de duplicidade assim que o usuário sai do campo, em vez de só
68	  // no /finalizar (último passo) — bem tarde pra descobrir que o CNPJ digitado
69	  // 3 passos atrás já está em uso.
70	  @Post('verificar-disponibilidade')
71	  @UseGuards(RestaurantOwnerGuard)
72	  async verificarDisponibilidade(
73	    @Req() req: any,
74	    @Body() body: { cnpj?: string; whatsapp?: string; email?: string },
75	  ) {
76	    const restaurantId: number = req.restaurantId;
77	    const duplicados = await this.checarDuplicados(restaurantId, {
78	      cnpj: this.normalizarDigitos(body.cnpj),
79	      whatsapp: this.normalizarDigitos(body.whatsapp),
80	      email: this.normalizarEmail(body.email),
81	    });
82	    return {
83	      cnpj_disponivel: !duplicados.cnpj,
84	      whatsapp_disponivel: !duplicados.whatsapp,
85	      email_disponivel: !duplicados.email,
86	    };
87	  }
88	
89	  // 1ª fase do cadastro: cria a loja só com nome + assinatura do plano
90	  // escolhido, e cobra a fatura do período atual na hora se o plano não tiver
91	  // trial. O resto do formulário (endereço, horários, tipo...) só é liberado
92	  // na wizard depois que essa fatura confirmar paga (ou, se for plano com
93	  // trial, direto). Idempotente: se o usuário já tem restaurante (reload no
94	  // meio do checkout), retorna o estado atual em vez de criar de novo.
95	  @Post('registrar-inicial')
96	  @UseGuards(JwtGuard)
97	  async registrarInicial(@Req() req: any, @Body() body: { name?: string; plano_id?: number }) {
98	    const userId: string = req.userId;
99	
100	    const { data: existing } = await this.supabase.client
101	      .from('restaurants')
102	      .select('id, name')
103	      .eq('user_id', userId)
104	      .maybeSingle();
105	
106	    let restaurant = existing;
107	    let precisaAssinar = false;
108	
109	    if (!restaurant) {
110	      if (!body.name?.trim()) throw new BadRequestException('Nome do estabelecimento é obrigatório.');
111	      if (!body.plano_id) throw new BadRequestException('Selecione um plano para continuar.');
112	
113	      const slug = body.name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').trim();
114	
115	      const { data: novo, error } = await this.supabase.client
116	        .from('restaurants')
117	        .insert({ name: body.name, user_id: userId, slug })
118	        .select('id, name')
119	        .single();
120	      if (error) throw error;
121	      restaurant = novo;
122	      precisaAssinar = true;
123	    } else if (body.plano_id) {
124	      // Já tem loja (voltou nesse passo, ou reload) — só reassina se o plano
125	      // escolhido agora for DIFERENTE do que já está na assinatura. Sem essa
126	      // checagem, trocar de plano na wizard e clicar Continuar de novo
127	      // ignorava a nova escolha e reaproveitava fatura/trial do plano antigo.
128	      const { assinatura } = await this.planos.buscarAssinaturaPorRestaurante(restaurant.id);
129	      precisaAssinar = assinatura.plano_id !== body.plano_id;
130	
131	      if (precisaAssinar) {
132	        // Role só eleva pra restaurant_owner no /finalizar — se ainda é
133	        // 'customer', o usuário está só comparando planos, nada foi pago.
134	        // Cancela fatura pendente do plano anterior pra não ficar presa
135	        // bloqueando o plano novo escolhido (ex: trial). Restrito a esse
136	        // estado pra não deixar um dono já pagante cancelar dívida real só
137	        // reenviando outro plano_id nesse endpoint.
138	        const { data: perfil } = await this.supabase.client
139	          .from('user_profiles').select('role').eq('id', userId).maybeSingle();
140	        if (perfil?.role !== 'restaurant_owner') {
141	          await this.supabase.client
142	            .from('plano_faturas')
143	            .update({ status: 'cancelada', atualizado_em: new Date().toISOString() })
144	            .eq('assinatura_id', assinatura.id)
145	            .in('status', ['pendente', 'vencida']);
146	        }
147	      }
148	    }
149	
150	    let status: { fatura_pendente_id: number | null };
151	    if (precisaAssinar) {
152	      // precisaAssinar só fica true quando body.plano_id já foi validado como
153	      // presente (loja nova) ou veio no body pra decidir a troca (loja existente).
154	      const planoId = body.plano_id as number;
155	      const plano = await this.planos.buscarPlano(planoId);
156	      await this.planos.atribuirAssinatura({ restaurantId: restaurant.id }, planoId);
157	
158	      // Sem trial: gera (forçado) a fatura do período atual pra cobrar já no
159	      // cadastro. Com trial, não força nada — fica pra próxima renovação natural.
160	      const temTrial = (plano.trial_dias ?? 0) > 0;
161	      status = await this.planos.sincronizarPeriodo({ restaurantId: restaurant.id }, !temTrial);
162	    } else {
163	      status = await this.planos.sincronizarPeriodo({ restaurantId: restaurant.id });
164	    }
165	
166	    if (!status.fatura_pendente_id) {
167	      // Assinou plano com trial (sem cobrança) — já vira dono aqui, sem esperar
168	      // o resto da wizard (endereço, horários...). Restrito a precisaAssinar pra
169	      // não elevar num reload de loja com assinatura cancelada (que também cai
170	      // em fatura_pendente_id null, mas não é uma assinatura ativa de verdade).
171	      if (precisaAssinar) await this.usuarios.sincronizarVinculoDono(restaurant.id, userId);
172	      return { restaurant, precisa_pagamento: false, fatura: null };
173	    }
174	
175	    const fatura = await this.planos.buscarFaturaDoRestaurante(restaurant.id, status.fatura_pendente_id);
176	    return { restaurant, precisa_pagamento: true, fatura };
177	  }
178	
179	  // 2ª fase: completa o cadastro (endereço, horários, tipo de estabelecimento)
180	  // e eleva o role pra restaurant_owner — só chamada depois que a wizard
181	  // liberou o formulário (plano pago ou em trial).
182	  @Post('finalizar')
183	  @UseGuards(RestaurantOwnerGuard)
184	  async finalizar(
185	    @Req() req: any,
186	    @Body()
187	    body: {
188	      name?: string;
189	      address?: string;
190	      state?: string;
191	      city?: string;
192	      neighborhood?: string;
193	      cep?: string;
194	      business_hours?: object;
195	      type_id?: number;
196	      cnpj?: string;
197	      whatsapp?: string;
198	      email?: string;
199	    },
200	  ) {
201	    const restaurantId: number = req.restaurantId;
202	    const userId: string = req.userId;
203	
204	    const cnpjNorm = this.normalizarDigitos(body.cnpj);
205	    const whatsappNorm = this.normalizarDigitos(body.whatsapp);
206	    const emailNorm = this.normalizarEmail(body.email);
207	
208	    // Última barreira antes de gravar — a wizard já checou isso passo a passo
209	    // (verificar-disponibilidade), mas dois cadastros concorrentes com o mesmo
210	    // CNPJ/WhatsApp/email só se pegam aqui (e na UNIQUE constraint do banco).
211	    const duplicados = await this.checarDuplicados(restaurantId, {
212	      cnpj: cnpjNorm,
213	      whatsapp: whatsappNorm,
214	      email: emailNorm,
215	    });
216	    const mensagens: string[] = [];
217	    if (duplicados.cnpj) mensagens.push('Este CNPJ já está cadastrado em outro estabelecimento.');
218	    if (duplicados.whatsapp) mensagens.push('Este WhatsApp já está cadastrado em outro estabelecimento.');
219	    if (duplicados.email) mensagens.push('Este email já está cadastrado em outro estabelecimento.');
220	    if (mensagens.length) throw new BadRequestException(mensagens.join(' '));
221	
222	    const campos: Record<string, any> = { updated_at: new Date().toISOString() };
223	    if (body.name !== undefined) campos.name = body.name;
224	    if (body.address !== undefined) campos.address = body.address;
225	    if (body.state !== undefined) campos.state = body.state;
226	    if (body.city !== undefined) campos.city = body.city;
227	    if (body.neighborhood !== undefined) campos.neighborhood = body.neighborhood;
228	    if (body.cep !== undefined) campos.cep = body.cep ? body.cep.replace(/\D/g, '') : null;
229	    if (body.business_hours !== undefined) campos.business_hours = body.business_hours;
230	    if (body.type_id !== undefined) campos.type_id = body.type_id;
231	    if (body.cnpj !== undefined) campos.cnpj = cnpjNorm;
232	    if (body.whatsapp !== undefined) campos.whatsapp = whatsappNorm;
233	    if (body.email !== undefined) campos.email = emailNorm;
234	
235	    const { data: restaurant, error } = await this.supabase.client
236	      .from('restaurants')
237	      .update(campos)
238	      .eq('id', restaurantId)
239	      .select()
240	      .single();
241	    if (error) {
242	      // Última rede de segurança contra corrida (dois cadastros com o mesmo
243	      // CNPJ/WhatsApp/email confirmando entre a checagem acima e este update).
244	      if ((error as any).code === '23505') {
245	        throw new BadRequestException('CNPJ, WhatsApp ou email já cadastrado em outro estabelecimento.');
246	      }
247	      throw error;
